const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();
    const K = nextInt();

    const parent = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) {
        parent[i] = i;
    }

    function find(i) {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            let nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    function union(i, j) {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) {
            parent[rootI] = rootJ;
            return true;
        }
        return false;
    }

    const roadsU = [];
    const roadsV = [];
    let hasWaterCycle = false;

    for (let i = 0; i < M; i++) {
        const u = nextInt();
        const v = nextInt();
        const t = nextInt();

        if (t === 1) {
            if (!union(u, v)) {
                hasWaterCycle = true;
            }
        } else {
            roadsU.push(u);
            roadsV.push(v);
        }
    }

    if (hasWaterCycle) {
        process.stdout.write("N\n");
        return;
    }

    let roadsToRemove = 0;
    const numRoads = roadsU.length;
    for (let i = 0; i < numRoads; i++) {
        const u = roadsU[i];
        const v = roadsV[i];
        if (!union(u, v)) {
            roadsToRemove++;
        }
    }

    if (roadsToRemove <= K) {
        process.stdout.write("S\n");
    } else {
        process.stdout.write("N\n");
    }
}

solve();
